SD.type():
# this is read-only if FS and VS are both read-only
# otherwise, it is read-only with hardware update

if (implemented?(ExtensionName::F) && (HW_MSTATUS_FS_DIRTY_UPDATE != "never")) {
  return CsrFieldType::ROH;
} else if (implemented?(ExtensionName::V) && (HW_MSTATUS_VS_DIRTY_UPDATE != "never")) {
  return CsrFieldType::ROH;
} else {
  return CsrFieldType::RO;
}

SD.reset_value():
# the reset value is known if both FS and VS are legal
# make this a function call so that it can be displayed succinctly in docs

if (mstatus_sd_has_known_reset()) {
  return mstatus_sd_reset_value();
} else {
  return UNDEFINED_LEGAL;
}

SBE.reset_value():
if (S_MODE_ENDIANNESS == "little") {
  return 0;
} else if (S_MODE_ENDIANNESS == "big") {
  return 1;
} else {
  return 0; # little endian
}

SXL.sw_write(csr_value):
if (csr_value.SXL < csr_value.UXL) {
  return CSR[mstatus].SXL;
} else if (csr_value.SXL < 1 || csr_value.SXL > 2) {
  # SXL != [1, 2] is not defined (3 reserved for RV128, but that isn't ratified)
  return CSR[mstatus].SXL;
} else {
  return csr_value.SXL;
}

SXL.reset_value():
if ($array_size(SXLEN) == 1 && $array_includes?(SXLEN, 32)) {
  return 1;
} else if ($array_size(SXLEN) == 1 && $array_includes?(SXLEN, 64)) {
  return 2;
} else {
  return 2;
}

UXL.sw_write(csr_value):
if (csr_value.SXL < csr_value.UXL) {
  return CSR[mstatus].UXL;
} else if (csr_value.UXL < 1 || csr_value.UXL > 2) {
  # UXL != [1, 2] is not defined (3 reserved for RV128, but that isn't ratified)
  return CSR[mstatus].UXL;
} else {
  return csr_value.UXL;
}

UXL.reset_value():
if ($array_size(UXLEN) == 1 && UXLEN[0] == 32) {
  return 1;
} else if ($array_size(UXLEN) == 1 && UXLEN[0] == 64) {
  return 2;
} else {
  return 2;
}

TVM.type():
if (CSR[misa].S == 1'b0) {
  return CsrFieldType::RO;
} else {
  return CsrFieldType::RW;
}

TVM.reset_value():
if (CSR[misa].S == 1'b0) {
  return 0;
} else if (MSTATUS_TVM_IMPLEMENTED) {
  return UNDEFINED_LEGAL;
} else {
  return 0;
}

TVM.sw_write(csr_value):
if (CSR[misa].S == 1'b0) {
  return 0;
} else if (MSTATUS_TVM_IMPLEMENTED) {
  return csr_value.TVM;
} else {
  return 0;
}

SUM.type():
# only writable if there is some translation supported
if (has_virt_mem?()) {
  return CsrFieldType::RW;
} else {
  return CsrFieldType::RO;
}

SUM.reset_value():
if (has_virt_mem?()) {
  return UNDEFINED_LEGAL;
} else {
  # read-only zero when there is no virtual memory
  return 0;
}

FS.type():
if (implemented?(ExtensionName::F) && (!MISA_CSR_IMPLEMENTED || CSR[misa].F == 1'b1)) {
  # "If the F extension is implemented, the FS field shall not be read-only zero."
  return CsrFieldType::RWH;
} else if (MISA_CSR_IMPLEMENTED && (CSR[misa].S == 1'b0) && (CSR[misa].F == 1'b0)) {
  # "If neither the F extension nor S-mode is implemented, then FS is read-only zero"
  return CsrFieldType::RO;
} else {
  # " If S-mode is implemented but the F extension is not, FS may optionally be read-only zero."
  # there will be no hardware update in this case because we know the F extension isn't implemented
  return $array_size(MSTATUS_FS_LEGAL_VALUES) == 1 ? CsrFieldType::RO : CsrFieldType::RW;
}

FS.sw_write(csr_value):
if (MISA_CSR_IMPLEMENTED && (CSR[misa].S == 1'b0) && (CSR[misa].F == 1'b0)) {
  # must be read-only-0
  return 0;
}
return $array_includes?(MSTATUS_FS_LEGAL_VALUES, csr_value.FS) ? csr_value.FS : UNDEFINED_LEGAL_DETERMINISTIC;

MPP.sw_write(csr_value):
if (csr_value.MPP == 2'b01 && !implemented?(ExtensionName::S)) {
  return UNDEFINED_LEGAL_DETERMINISTIC;
} else if (csr_value.MPP == 2'b00 && !implemented?(ExtensionName::U)) {
  return UNDEFINED_LEGAL_DETERMINISTIC;
} else if (csr_value.MPP == 2'b10) {
  # never a valid value
  return UNDEFINED_LEGAL_DETERMINISTIC;
} else {
  return csr_value.MPP;
}

VS.type():
if (implemented?(ExtensionName::V) && (!MISA_CSR_IMPLEMENTED || CSR[misa].V == 1'b1)) {
  # "If the V extension is implemented, the VS field shall not be read-only zero."
  return CsrFieldType::RWH;
} else if (MISA_CSR_IMPLEMENTED && (CSR[misa].S == 1'b0) && (CSR[misa].V == 1'b0)) {
  # "If neither the V extension nor S-mode is implemented, then VS is read-only zero"
  return CsrFieldType::RO;
} else {
  # " If S-mode is implemented but the V extension is not, VS may optionally be read-only zero."
  # there will be no hardware update in this case because we know the V extension isn't implemented
  return $array_size(MSTATUS_VS_LEGAL_VALUES) == 1 ? CsrFieldType::RO : CsrFieldType::RW;
}

VS.reset_value():
if (CSR[misa].V == 1'b1){
  return UNDEFINED_LEGAL;
} else if ((CSR[misa].S == 1'b0) && (CSR[misa].V == 1'b0)) {
  # must be read-only-0
  return 0;
} else {
  # there will be no hardware update in this case because we know the V extension isn't implemented
  if ($array_size(MSTATUS_VS_LEGAL_VALUES) == 0) {
    return 0;
  } else if ($array_size(MSTATUS_VS_LEGAL_VALUES) == 1) {
    return MSTATUS_VS_LEGAL_VALUES[0];
  } else {
    return UNDEFINED_LEGAL;
  }
}

VS.sw_write(csr_value):
if (implemented?(ExtensionName::V) && CSR[misa].V == 1'b1){
  return $array_includes?(MSTATUS_VS_LEGAL_VALUES, csr_value.VS) ? csr_value.VS : UNDEFINED_LEGAL_DETERMINISTIC;
} else if (!implemented?(ExtensionName::S) && !implemented?(ExtensionName::V)) {
  # must be read-only-0
  return 0;
} else {
  # there will be no hardware update in this case because we know the V extension isn't implemented
  return $array_includes?(MSTATUS_VS_LEGAL_VALUES, csr_value.VS) ? csr_value.VS : UNDEFINED_LEGAL_DETERMINISTIC;
}

SPP.sw_write(csr_value):
if (csr_value.SPP == 2'b10) {
  return UNDEFINED_LEGAL_DETERMINISTIC;
} else {
  return csr_value.SPP;
}

UBE.reset_value():
if (U_MODE_ENDIANNESS == "little") {
  return 0;
} else if (U_MODE_ENDIANNESS == "big") {
  return 1;
} else {
  return UNDEFINED_LEGAL;
}

HCONTEXT.sw_write(csr_value):
# check if MCONTEXT is available
if (!MCONTEXT_AVAILABLE) {
  unimplemented_csr($encoding);
}

# enforce width of HCONTEXT
Bits<14> hcontext_value = csr_value.HCONTEXT & ((14'1 << DBG_HCONTEXT_WIDTH) - 1);
return hcontext_value;

sw_read():
# check if MCONTEXT is available
if (!MCONTEXT_AVAILABLE) {
  unimplemented_csr($encoding);
}
return $bits(CSR[mcontext]);

# access is determined by *counteren CSRs
if (mode() == PrivilegeMode::S) {
  # S-mode is present ->
  #   mcounteren determines access in S-mode
  if (CSR[mcounteren].CY == 1'b0) {
    raise(ExceptionCode::IllegalInstruction, mode(), $encoding);
  }
} else if (mode() == PrivilegeMode::U) {
  if (CSR[misa].S == 1'b1) {
    # S-mode is present ->
    #   mcounteren and scounteren together determine access in U-mode
    if ((CSR[mcounteren].CY & CSR[scounteren].CY) == 1'b0) {
      raise(ExceptionCode::IllegalInstruction, mode(), $encoding);
    }
  } else if (CSR[mcounteren].CY == 1'b0) {
    # S-mode is not present ->
    #   mcounteren determines access in U-mode
    raise(ExceptionCode::IllegalInstruction, mode(), $encoding);
  }
} else if (mode() == PrivilegeMode::VS) {
  # access in VS mode
  if (CSR[hcounteren].CY == 1'b0 && CSR[mcounteren].CY == 1'b1) {
    raise(ExceptionCode::VirtualInstruction, mode(), $encoding);
  } else if (CSR[mcounteren].CY == 1'b0) {
    raise(ExceptionCode::IllegalInstruction, mode(), $encoding);
  }
} else if (mode() == PrivilegeMode::VU) {
  # access in VU mode
  if (((CSR[hcounteren].CY & CSR[scounteren].CY) == 1'b0) && (CSR[mcounteren].CY == 1'b1)) {
    raise(ExceptionCode::VirtualInstruction, mode(), $encoding);
  } else if (CSR[mcounteren].CY == 1'b0) {
    raise(ExceptionCode::IllegalInstruction, mode(), $encoding);
  }
}

# since the counter may be shared among harts, reads must be handled
# as a builtin function
return read_mcycle();

# access is determined by *counteren CSRs
if (mode() == PrivilegeMode::S) {
  # S-mode is present ->
  #   mcounteren determines access in S-mode
  if (CSR[mcounteren].IR == 1'b0) {
    raise(ExceptionCode::IllegalInstruction, mode(), $encoding);
  }
} else if (mode() == PrivilegeMode::U) {
  if (CSR[misa].S == 1'b1) {
    # S-mode is present ->
    #   mcounteren and scounteren together determine access in U-mode
    if ((CSR[mcounteren].IR & CSR[scounteren].IR) == 1'b0) {
      raise(ExceptionCode::IllegalInstruction, mode(), $encoding);
    }
  } else if (CSR[mcounteren].IR == 1'b0) {
    # S-mode is not present ->
    #   mcounteren determines access in U-mode
    raise(ExceptionCode::IllegalInstruction, mode(), $encoding);
  }
} else if (mode() == PrivilegeMode::VS) {
  # access in VS mode
  if (CSR[hcounteren].IR == 1'b0 && CSR[mcounteren].IR == 1'b1) {
    raise(ExceptionCode::VirtualInstruction, mode(), $encoding);
  } else if (CSR[mcounteren].IR == 1'b0) {
    raise(ExceptionCode::IllegalInstruction, mode(), $encoding);
  }
} else if (mode() == PrivilegeMode::VU) {
  # access in VU mode
  if (((CSR[hcounteren].IR & CSR[scounteren].IR) == 1'b0) && (CSR[mcounteren].IR == 1'b1)) {
    raise(ExceptionCode::VirtualInstruction, mode(), $encoding);
  } else if (CSR[mcounteren].IR == 1'b0) {
    raise(ExceptionCode::IllegalInstruction, mode(), $encoding);
  }
}

return $bits(CSR[minstret]);

if (implemented?(ExtensionName::C) && CSR[misa].C == 1'b1) {
  return CSR[sepc].PC & ~64'b1;
} else {
  return CSR[sepc].PC;
}

VALUE.sw_write(csr_value):
if ((mode() < PrivilegeMode::M && CSR[menvcfg].SSE == 0) ||
    (mode() == PrivilegeMode::U && CSR[senvcfg].SSE == 0)) {
  raise(ExceptionCode::IllegalInstruction, mode(), $encoding);
} else if ((mode() == PrivilegeMode::VS && CSR[henvcfg].SSE == 0) ||
           (mode() == PrivilegeMode::VU && (CSR[henvcfg].SSE == 0 || CSR[senvcfg].SSE == 0))) {
  raise(ExceptionCode::VirtualInstruction, mode(), $encoding);
} else {
  return csr_value.VALUE;
}

sw_read():
if ((mode() < PrivilegeMode::M && CSR[menvcfg].SSE == 0) ||
    (mode() == PrivilegeMode::U && CSR[senvcfg].SSE == 0)) {
  raise(ExceptionCode::IllegalInstruction, mode(), $encoding);
} else if ((mode() == PrivilegeMode::VS && CSR[henvcfg].SSE == 0) ||
           (mode() == PrivilegeMode::VU && (CSR[henvcfg].SSE == 0 || CSR[senvcfg].SSE == 0))) {
  raise(ExceptionCode::VirtualInstruction, mode(), $encoding);
} else if (xlen() == 32) {
  return ($bits(CSR[ssp]) & ~MXLEN'3);
}
return ($bits(CSR[ssp]) & ~MXLEN'7);

CBIE.sw_write(csr_value):
if (csr_value.CBIE == 0 || csr_value.CBIE == 1 || csr_value.CBIE == 3) {
  return csr_value.CBIE;
} else {
  return UNDEFINED_LEGAL_DETERMINISTIC;
}

sw_read():
Bits<64> value = $bits(CSR[senvcfg]);
if (implemented?(ExtensionName::Zicfiss) && (CSR[menvcfg].SSE == 0 || CSR[henvcfg].SSE == 0)) {
  # senvcfg.SSE must read-as-zero
  value = value & ~(1 `<< 3);
}
return value;

if (implemented?(ExtensionName::C) && CSR[misa].C == 1'b1) {
  return CSR[mepc].PC & ~64'b1;
} else {
  return CSR[mepc].PC;
}

MODE.sw_write(csr_value):
if (STVEC_MODE_DIRECT && csr_value.MODE == 0) {
  return 0;
} else if (STVEC_MODE_VECTORED && csr_value.MODE == 1) {
  return 1;
} else {
  return UNDEFINED_LEGAL_DETERMINISTIC;
}

DATA.sw_write(csr_value):
# For every bit in an mstateen CSR that is zero, the same bit
# appears as read-only zero in the matching sstateen CSR.
Bits<64> mstateen1_mask = $bits(CSR[mstateen1]);
Bits<64> data_value = csr_value.DATA & mstateen1_mask;

# For every bit in an hstateen CSR that is zero, the same bit
# appears as read-only zero in sstateen when accessed in VS-mode.
if (mode() == PrivilegeMode::VS) {
  Bits<64> hstateen1_mask = $bits(CSR[hstateen1]);
  data_value = data_value & hstateen1_mask;
}

return data_value;

sw_read():
# For every bit in an mstateen CSR that is zero, the same bit
# appears as read-only zero in the matching sstateen CSR.
Bits<64> mstateen1_mask = $bits(CSR[mstateen1]);
Bits<64> sstateen1_value = $bits(CSR[sstateen1]) & mstateen1_mask;

# For every bit in an hstateen CSR that is zero, the same bit
# appears as read-only zero in sstateen when accessed in VS-mode.
if (mode() == PrivilegeMode::VS) {
  Bits<64> hstateen1_mask = $bits(CSR[hstateen1]);
  sstateen1_value = sstateen1_value & hstateen1_mask;
}

return sstateen1_value;

# for every bit in an mstateen CSR that is zero, the same bit
# appears as read-only zero in the matching hstateen CSR

Bits<64> mstateen2_mask = $bits(CSR[mstateen2]);
Bits<64> hstateen2_value = $bits(CSR[hstateen2]) & mstateen2_mask;
return hstateen2_value;

DATA.sw_write(csr_value):
# For every bit in an mstateen CSR that is zero, the same bit
# appears as read-only zero in the matching sstateen CSR.
Bits<64> mstateen2_mask = $bits(CSR[mstateen2]);
Bits<64> data_value = csr_value.DATA & mstateen2_mask;

# For every bit in an hstateen CSR that is zero, the same bit
# appears as read-only zero in sstateen when accessed in VS-mode.
if (mode() == PrivilegeMode::VS) {
  Bits<64> hstateen2_mask = $bits(CSR[hstateen2]);
  data_value = data_value & hstateen2_mask;
}

return data_value;

sw_read():
# For every bit in an mstateen CSR that is zero, the same bit
# appears as read-only zero in the matching sstateen CSR.
Bits<64> mstateen2_mask = $bits(CSR[mstateen2]);
Bits<64> sstateen2_value = $bits(CSR[sstateen2]) & mstateen2_mask;

# For every bit in an hstateen CSR that is zero, the same bit
# appears as read-only zero in sstateen when accessed in VS-mode.
if (mode() == PrivilegeMode::VS) {
  Bits<64> hstateen2_mask = $bits(CSR[hstateen2]);
  sstateen2_value = sstateen2_value & hstateen2_mask;
}

return sstateen2_value;

# NOTE: The spec specifically says that reading cycleh when XLEN == 64 always causes
#       IllegalInstruction exception even if it would otherwise be changed to a `VirtualInstruction
#       exception. We don't have to explicitly check this here because it is already implied by
#       the base constraint

# access is determined by *counteren CSRs
if (mode() == PrivilegeMode::S) {
  # S-mode is present ->
  #   mcounteren determines access in S-mode
  if (CSR[mcounteren].CY == 1'b0) {
    raise(ExceptionCode::IllegalInstruction, mode(), $encoding);
  }
} else if (mode() == PrivilegeMode::U) {
  if (CSR[misa].S == 1'b1) {
    # S-mode is present ->
    #   mcounteren and scounteren together determine access in U-mode
    if ((CSR[mcounteren].CY & CSR[scounteren].CY) == 1'b0) {
      raise(ExceptionCode::IllegalInstruction, mode(), $encoding);
    }
  } else if (CSR[mcounteren].CY == 1'b0) {
    # S-mode is not present ->
    #   mcounteren determines access in U-mode
    raise(ExceptionCode::IllegalInstruction, mode(), $encoding);
  }
} else if (mode() == PrivilegeMode::VS) {
  # access in VS mode
  if (CSR[hcounteren].CY == 1'b0 && CSR[mcounteren].CY == 1'b1) {
    raise(ExceptionCode::VirtualInstruction, mode(), $encoding);
  } else if (CSR[mcounteren].CY == 1'b0) {
    raise(ExceptionCode::IllegalInstruction, mode(), $encoding);
  }
} else if (mode() == PrivilegeMode::VU) {
  # access in VU mode
  if (((CSR[hcounteren].CY & CSR[scounteren].CY) == 1'b0) && (CSR[mcounteren].CY == 1'b1)) {
    raise(ExceptionCode::VirtualInstruction, mode(), $encoding);
  } else if (CSR[mcounteren].CY == 1'b0) {
    raise(ExceptionCode::IllegalInstruction, mode(), $encoding);
  }
}

# since the counter may be shared among harts, reads must be handled
# as a builtin function
return read_mcycle()[63:32];

BASE.type():
if (JVT_READ_ONLY) {
  return CsrFieldType::RO;
}
else {
  return CsrFieldType::RW;
}

BASE.sw_write(csr_value):
if (( mode() != PrivilegeMode::M && implemented?(ExtensionName::Smstateen)
      && CSR[mstateen0].JVT == 1'b0 )
    ||
    ( mode() == PrivilegeMode::U && implemented?(ExtensionName::Ssstateen)
      && CSR[sstateen0].JVT == 1'b0 )
    ||
    ( mode() == PrivilegeMode::VS && implemented?(ExtensionName::Ssstateen)
      && CSR[hstateen0].JVT == 1'b0 )
    ||
    ( mode() == PrivilegeMode::VU && implemented?(ExtensionName::Ssstateen)
      && (CSR[sstateen0].JVT == 1'b0 || CSR[hstateen0].JVT == 1'b0) )) {

  unimplemented_csr($encoding);
}
else {
  if (JVT_BASE_TYPE == "custom") {
    unpredictable("jvt.BASE has custom behavior");
  } else {
    return csr_value.BASE & (JVT_BASE_MASK >> 6);
  }
  return csr_value.BASE == 0 ? 0 : UNDEFINED_LEGAL_DETERMINISTIC;
}

MODE.type():
if (JVT_READ_ONLY) {
  return CsrFieldType::RO;
}
else {
  return CsrFieldType::RW;
}

MODE.sw_write(csr_value):
if (SATP_MODE_BARE && (csr_value.MODE == 0)) {
  # In Bare, ASID and PPN must be zero, else the entire write is ignored
  if (csr_value.ASID == 0 && csr_value.PPN == 0) {
    if (CSR[satp].MODE != 0) {
      # changes *to* Bare mode take effect immediately without needing sfence.vma
      # thus, an implicit sfence.vma occurs now
      VmaOrderType order_type;
      order_type.global = true;
      order_pgtbl_writes_before_vmafence(order_type);

      invalidate_translations(order_type);

      order_pgtbl_reads_after_vmafence(order_type);
    }
    return csr_value.MODE;
  } else {
    return UNDEFINED_LEGAL_DETERMINISTIC;
  }
}
else if (implemented?(ExtensionName::Sv32) && csr_value.MODE == 1) {
  if (CSR[satp].MODE == 0) {
    # changes *from* Bare mode take effect immediately without needing sfence.vma
    # thus, an implicit sfence.vma occurs now
    VmaOrderType order_type;
    order_type.global = true;
    order_pgtbl_writes_before_vmafence(order_type);

    invalidate_translations(order_type);

    order_pgtbl_reads_after_vmafence(order_type);
  }
  return csr_value.MODE;
}else if (implemented?(ExtensionName::Sv39) && csr_value.MODE == 8) {
  if (CSR[satp].MODE == 0) {
    # changes *from* Bare mode take effect immediately without needing sfence.vma
    # thus, an implicit sfence.vma occurs now
    VmaOrderType order_type;
    order_type.global = true;
    order_pgtbl_writes_before_vmafence(order_type);

    invalidate_translations(order_type);

    order_pgtbl_reads_after_vmafence(order_type);
  }
  return csr_value.MODE;
}
else if (implemented?(ExtensionName::Sv48) && csr_value.MODE == 9) {
  if (CSR[satp].MODE == 0) {
    # changes *from* Bare mode take effect immediately without needing sfence.vma
    # thus, an implicit sfence.vma occurs now
    VmaOrderType order_type;
    order_type.global = true;
    order_pgtbl_writes_before_vmafence(order_type);

    invalidate_translations(order_type);

    order_pgtbl_reads_after_vmafence(order_type);
  }

  return csr_value.MODE;
}
else if (implemented?(ExtensionName::Sv57) && csr_value.MODE == 10) {
  if (CSR[satp].MODE == 0) {
    # changes *from* Bare mode take effect immediately without needing sfence.vma
    # thus, an implicit sfence.vma occurs now
    VmaOrderType order_type;
    order_type.global = true;
    order_pgtbl_writes_before_vmafence(order_type);

    invalidate_translations(order_type);

    order_pgtbl_reads_after_vmafence(order_type);
  }

  return csr_value.MODE;
}
else {
  return UNDEFINED_LEGAL_DETERMINISTIC;
}

ASID.sw_write(csr_value):
if (csr_value.MODE == 0) {
  # when MODE == Bare, PPN and ASID must be zero
  if (csr_value.ASID == 0 && csr_value.PPN == 0) {
    return csr_value.ASID;
  } else {
    return UNDEFINED_LEGAL_DETERMINISTIC;
  }
} else {
  XReg shamt = (xlen() == 32 || (CSR[mstatus].SXL == $bits(XRegWidth::XLEN32))) ? 9 : 16;
  XReg all_ones = ((MXLEN'1 << shamt) - 1);
  XReg largest_allowed_asid = (MXLEN'1 << shamt) - 1;

  if (csr_value.ASID == all_ones) {
    # the specification states that if all 1's are written to the ASID field, then
    # you must return the largest asid
    return largest_allowed_asid;
  } else if (csr_value.ASID > largest_allowed_asid) {
    # ... but is silent on what happens on any other illegal value
    return UNDEFINED_LEGAL_DETERMINISTIC;
  } else {
    # unrestricted
    return csr_value.ASID;
  }
}

PPN.sw_write(csr_value):
if (csr_value.MODE == 0) {
  # when MODE == Bare, PPN and ASID must be zero
  if (csr_value.ASID == 0 && csr_value.PPN == 0) {
    return csr_value.PPN;
  } else {
    return UNDEFINED_LEGAL_DETERMINISTIC;
  }
} else {
  # unrestricted
  return csr_value.PPN;
}

INT.sw_write(csr_value):
